(async()=>{
if(new URLSearchParams(location.search).get('edit')!=='1')return;
const api=window.WN_CONTENT,schema=window.WN_SCHEMA;let values=await window.WN_READY||{},snapshot=null,active=null,dirty=false,processing=false;
const css=document.createElement('link');css.rel='stylesheet';css.href='inline-editor.css';document.head.append(css);document.body.classList.add('wn-edit-mode');document.title='위닝텍 | 홈페이지 직접 편집';
const toolbar=document.createElement('div');toolbar.className='wn-edit-toolbar';toolbar.innerHTML='<div><strong>관리자 편집 모드</strong><span>화면의 편집 버튼을 눌러 문구·이미지·배경을 수정하세요.</span></div><div class="wn-edit-actions"><button type="button" data-action="save">저장</button><button type="button" data-action="cancel">취소</button><button type="button" data-action="export">파일 내보내기</button><button type="button" data-action="import">파일 불러오기</button><a href="index.html" target="_blank" rel="noopener">홈페이지 보기 ↗</a></div><p role="status" aria-live="polite">저장은 현재 브라우저에 적용됩니다. 전체 방문자 반영은 내보낸 content.json을 GitHub에 업로드하세요.</p>';document.body.append(toolbar);
const status=toolbar.querySelector('[role=status]');function say(text){status.textContent=text;}
const sections=[...document.querySelectorAll('main section')];const entries=new Map(schema.fields.map(f=>[f.key,f]));
function fieldValue(f){return Object.hasOwn(values,f.key)?values[f.key]:api.defaultValue(f);}
function end(){document.querySelectorAll('.wn-inline-text').forEach(el=>{el.removeAttribute('contenteditable');el.removeAttribute('spellcheck');el.classList.remove('wn-inline-text');});document.querySelectorAll('.wn-image-control,.wn-background-control,.wn-link-control').forEach(el=>el.remove());sections.forEach(s=>s.classList.remove('wn-edit-active'));active=null;snapshot=null;toolbar.classList.remove('editing');}
function cancel(){if(snapshot){values=snapshot;api.apply(values);}end();dirty=false;say('편집을 취소했습니다.');}
async function imageData(file){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('8MB 이하 PNG, JPEG, WebP 이미지를 선택해주세요.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(bitmap.width*scale));c.height=Math.max(1,Math.round(bitmap.height*scale));c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();return c.toDataURL('image/webp',.86);}
function pickImage(key){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';input.hidden=true;document.body.append(input);input.addEventListener('change',async()=>{processing=true;try{const data=await imageData(input.files[0]);values[key]=data;api.apply(values);dirty=true;say('이미지를 교체했습니다. 저장을 눌러 적용하세요.');}catch(e){say(e.message);}finally{processing=false;input.remove();}});input.click();}
function start(section){if(active===section)return;if(active&&dirty&&!confirm('현재 편집을 취소하고 다른 영역을 편집할까요?'))return;if(active)cancel();active=section;snapshot=structuredClone(values);section.classList.add('wn-edit-active');toolbar.classList.add('editing');
section.querySelectorAll('[data-content-key]').forEach(el=>{const f=entries.get(el.dataset.contentKey);if(!f||f.kind==='image')return;el.contentEditable='plaintext-only';el.spellcheck=true;el.classList.add('wn-inline-text');el.oninput=()=>{const text=el.innerText;values[f.key]=f.kind==='link'?{...fieldValue(f),text}:text;dirty=true;};
if(f.kind==='link'){el.onclick=e=>e.preventDefault();const button=document.createElement('button');button.type='button';button.className='wn-link-control';button.textContent='연결 주소 수정';button.onclick=()=>{const next=prompt('연결 주소 (https:, mailto:, tel:)',fieldValue(f).href);if(next===null)return;try{const value={...fieldValue(f),href:next};api.validate({version:1,fields:{[f.key]:value}});values[f.key]=value;el.href=next;dirty=true;say('연결 주소를 수정했습니다.');}catch(e){say(e.message);}};el.insertAdjacentElement('afterend',button);}
});
section.querySelectorAll('img[data-content-key]').forEach(image=>{const button=document.createElement('button');button.type='button';button.className='wn-image-control';button.textContent='이미지 교체';button.setAttribute('aria-label',image.alt+' 이미지 교체');button.onclick=()=>pickImage(image.dataset.contentKey);image.parentElement.classList.add('wn-image-host');image.insertAdjacentElement('afterend',button);});
const bg=schema.fields.find(f=>f.kind==='background'&&f.key===section.dataset.backgroundKey);if(bg){const bar=document.createElement('div');bar.className='wn-background-control';const replace=document.createElement('button');replace.type='button';replace.textContent='배경 이미지 교체';replace.onclick=()=>pickImage(bg.key);const clear=document.createElement('button');clear.type='button';clear.textContent='배경 이미지 제거';clear.onclick=()=>{values[bg.key]='';api.apply(values);dirty=true;};bar.append(replace,clear);section.append(bar);}
say('문구를 클릭해 입력하고, 이미지·배경 교체 버튼으로 사진을 바꾼 뒤 저장하세요.');}
sections.forEach((section,index)=>{const button=document.createElement('button');button.type='button';button.className='wn-section-edit';button.textContent='✎ 편집';button.setAttribute('aria-label',(section.querySelector('h1,h2')?.textContent.trim()||'영역 '+index)+' 편집');button.onclick=()=>start(section);section.classList.add('wn-edit-section');section.append(button);});
toolbar.querySelector('[data-action=save]').onclick=async()=>{if(processing){say('이미지 처리가 끝난 뒤 저장해주세요.');return;}try{api.validate({version:1,fields:values});await api.write(values);end();dirty=false;const channel=new BroadcastChannel('winningtec-content');channel.postMessage('updated');channel.close();say('저장했습니다. 현재 브라우저의 홈페이지에 적용됩니다.');}catch(e){say('저장 실패: '+e.message);}};
toolbar.querySelector('[data-action=cancel]').onclick=cancel;
toolbar.querySelector('[data-action=export]').onclick=()=>{try{if(processing)throw Error('이미지 처리가 끝난 뒤 내보내세요.');api.validate({version:1,fields:values});const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,fields:values},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='content.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);say('내보낸 content.json을 GitHub의 dist/content.json에 올리면 전체 방문자에게 반영됩니다.');}catch(e){say(e.message);}};
toolbar.querySelector('[data-action=import]').onclick=()=>{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;document.body.append(input);input.onchange=async()=>{try{const file=input.files[0];if(!file||file.size>20*1024*1024)throw Error('20MB 이하 콘텐츠 파일을 선택해주세요.');const next=api.validate(JSON.parse(await file.text()));await api.write(next,schema.fields.map(f=>f.key).filter(k=>!Object.hasOwn(next,k)));values={...await api.published(),...next};end();api.apply(values);dirty=false;say('파일을 불러와 현재 브라우저에 저장했습니다.');}catch(e){say(e.message);}finally{input.remove();}};input.click();};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
})();
